package com.himeros.messaging;import jakarta.validation.constraints.NotBlank;import java.security.Principal;import java.util.UUID;import org.springframework.messaging.handler.annotation.*;import org.springframework.stereotype.Controller;@Controller public class MessagingWebSocketController{private final MessagingService service;public MessagingWebSocketController(MessagingService s){service=s;}@MessageMapping("/conversations/{conversationId}/messages")public MessagingService.MessageView send(@DestinationVariable UUID conversationId,@Payload Send payload,Principal principal){return service.send(UUID.fromString(principal.getName()),conversationId,payload.content());}public record Send(@NotBlank String content){}}
